  function customerWalletPanelHtml(context,amount,request,key){if(amount===null)return '';const current=request?.key===key,confirmed=current&&request.status==='confirmed';return `<div class="customer-wallet-panel"><div class="customer-wallet-top"><span class="customer-wallet-mark">${icon('grid')}</span><div><strong>Pay with the customer's VLINKPAY Wallet</strong><small>Guest scans or approves the payment request in their own wallet.</small></div></div><div class="summary-line"><span>Wallet portion to collect</span><strong>${money(amount)}</strong></div><div class="customer-wallet-status ${confirmed?'confirmed':''}" role="status">${confirmed?'Demo payment confirmed':current&&request.status==='declined'?'Demo request declined · create a new request':current?'Awaiting customer approval':request?'Amount or customer changed · create a new request':'No payment request yet'}</div><div class="customer-wallet-actions"><button type="button" class="btn btn-secondary" data-action="${context}-wallet-request" ${cents(amount)===0?'disabled':''}>${current?'Refresh demo request':'Create demo request'}</button><button type="button" class="btn btn-secondary" data-action="${context}-wallet-confirm" ${!current||confirmed||request?.status==='declined'?'disabled':''}>Mark demo paid</button><button type="button" class="btn btn-secondary" data-action="${context}-wallet-decline" ${!current||confirmed||request?.status==='declined'?'disabled':''}>Decline demo</button></div><p>This is a design preview. A live checkout must wait for VLINKPAY's verified payment status; never mark it paid from a cashier button.</p></div>`}
