  function utilityTileHtml(item,index,total){const opened=state.productMenuOpen===item.id,button=item.local?`<button type="button" class="desk-utility-link desk-utility-trigger" data-action="utility-open-pos-menu" aria-label="Open POS menu"><span class="desk-utility-icon">${icon(item.icon)}</span><span class="desk-utility-copy"><strong>${esc(item.label)}</strong><small>${esc(item.desc)}</small></span><span class="desk-utility-arrow" aria-hidden="true">⌄</span></button>`:item.sections?`<button type="button" class="desk-utility-link desk-utility-trigger" data-action="utility-product-toggle" data-id="${item.id}" aria-expanded="${opened}" aria-controls="product-tools-panel"><span class="desk-utility-icon">${icon(item.icon)}</span><span class="desk-utility-copy"><strong>${esc(item.label)}</strong><small>${esc(item.desc)}</small></span><span class="desk-utility-arrow" aria-hidden="true">${opened?'⌃':'⌄'}</span></button>`:`<a class="desk-utility-link" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(item.label)} in a new tab"><span class="desk-utility-icon">${icon(item.icon)}</span><span class="desk-utility-copy"><strong>${esc(item.label)}</strong><small>${esc(item.desc)}</small></span><span class="desk-utility-arrow" aria-hidden="true">↗</span></a>`;return `<div class="desk-utility-item ${opened?'active':''}" style="--accent:${item.accent};--soft:${item.soft}">${button}</div>`}
  function supportPanelHtml(){const topic=supportTopics.find(entry=>entry.id===state.supportTopic)||supportTopics[0];return `<div class="support-tools" id="product-tools-panel" aria-label="Support channels"><div class="ai-hub-tools-head"><div><strong>Support at the POS</strong><span>Choose the issue first, then the fastest support channel.</span></div><button type="button" data-action="utility-product-toggle" data-id="support" aria-label="Close Support menu">×</button></div><div class="support-topic-list" role="group" aria-label="Support issue">${supportTopics.map(entry=>`<button type="button" class="${topic.id===entry.id?'selected':''}" data-action="support-topic" data-id="${entry.id}" aria-pressed="${topic.id===entry.id}">${esc(entry.label)}</button>`).join('')}</div><p class="support-topic-hint"><b>${esc(topic.team)}</b> · ${esc(topic.hint)}</p><div class="support-channel-grid"><article class="support-channel"><span class="support-channel-icon">☎</span><div><strong>Call ${esc(topic.team)}</strong><small>Route directly to the team for this issue. Show hours and a callback option when offline.</small></div><button type="button" class="support-channel-button" data-action="support-preview" data-value="call">Call team →</button><span class="support-channel-status">Prototype · line to connect</span></article><article class="support-channel"><span class="support-channel-icon">✉</span><div><strong>Email / support ticket</strong><small>Send a written request about ${esc(topic.label)} with a ticket number for follow-up.</small></div><a class="support-channel-button" href="https://nexoratouch.com/dashboard/support" target="_blank" rel="noopener noreferrer" aria-label="Open Nexora support ticket in a new tab">Open ticket ↗</a><span class="support-channel-status available">Available on Nexora now</span></article><article class="support-channel"><span class="support-channel-icon">◌</span><div><strong>Live chat</strong><small>Chat with ${esc(topic.team)} while this POS ticket stays open.</small></div><button type="button" class="support-channel-button" data-action="support-preview" data-value="chat">Open chat →</button><span class="support-channel-status">Prototype · chat to connect</span></article></div><p class="support-notice" role="status">${esc(state.supportNotice||'Production should show the configured number, chat availability, and support hours before connecting.')}</p><p class="support-privacy">Do not send a guest's phone number, payment details, or full ticket automatically. Ask the operator before attaching diagnostic details.</p></div>`}
  function productPanelHtml(){const item=deskUtilities.find(entry=>entry.id===state.productMenuOpen);if(item?.id==='support')return supportPanelHtml();if(!item?.sections)return '';const dailyIds=productDailyOrder[item.id]||[],daily=dailyIds.map(id=>item.sections.find(section=>section.id===id)).filter(Boolean),more=item.sections.filter(section=>!dailyIds.includes(section.id));const link=(section,primary)=>`<a class="product-tool-link ${primary?'product-tool-primary':'product-tool-secondary'}" href="${esc(section.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(item.label)} ${esc(section.label)} in a new tab">${primary?`<span class="product-tool-icon">${icon(productToolIcons[section.id]||'grid')}</span>`:''}<span class="product-tool-copy"><b>${esc(section.label)}</b><small>${esc(section.desc)}</small></span><span class="product-tool-arrow" aria-hidden="true">↗</span></a>`;return `<div class="ai-hub-tools product-priority-panel" id="product-tools-panel"><div class="ai-hub-tools-head"><div><strong>${esc(item.label)}</strong><span>Frequently used tools first · ${item.sections.length} tools</span></div><button type="button" data-action="utility-product-toggle" data-id="${item.id}" aria-label="Close ${esc(item.label)} menu">×</button></div><div class="ai-hub-section-grid"><div class="product-group-heading"><strong>DAILY FRONT DESK</strong><span>Booking, guest service, and payments</span></div>${daily.map(section=>link(section,true)).join('')}<div class="product-group-heading product-group-secondary"><strong>MORE TOOLS</strong><span>Campaigns, reports, and setup</span></div>${more.map(section=>link(section,false)).join('')}</div><p>Priority reflects the front desk workflow. Nexora can refine the order using real usage data; account permissions still apply.</p></div>`}

  function utilityTriggerHtml(){return `<button type="button" class="pos-header-products ${state.utilityMenuOpen?'active':''}" data-action="utility-toggle" aria-expanded="${state.utilityMenuOpen}" aria-controls="nexora-products-panel">${icon('grid')}<span>Nexora products</span><small>${deskUtilities.length}</small><span aria-hidden="true">${state.utilityMenuOpen?'⌃':'⌄'}</span></button>`}
  function utilityHtml(){if(!state.utilityMenuOpen)return '<section id="nexora-products-panel" hidden></section>';const ordered=state.utilityOrder.map(id=>deskUtilities.find(item=>item.id===id)).filter(Boolean);return `<section class="desk-utilities panel is-open" id="nexora-products-panel" aria-label="Nexora products inside POS"><div class="desk-utilities-body"><div class="desk-utilities-head"><div><p class="desk-kicker">QUICK ACCESS</p><h2>Products at your POS</h2><p>Open tools here while keeping this POS ticket in place.</p></div><div class="pos-nav-tools"><div class="pos-layout-toggle" role="group" aria-label="Products menu layout"><button type="button" class="${state.utilityLayout==='cards'?'selected':''}" data-action="utility-layout" data-value="cards" aria-pressed="${state.utilityLayout==='cards'}">${icon('grid')} Cards</button><button type="button" class="${state.utilityLayout==='compact'?'selected':''}" data-action="utility-layout" data-value="compact" aria-pressed="${state.utilityLayout==='compact'}">${icon('menu')} Compact</button></div></div></div><div class="desk-utility-grid ${state.utilityLayout}">${ordered.map((item,index)=>utilityTileHtml(item,index,ordered.length)).join('')}</div>${productPanelHtml()}</div></section>`}

  const liveFrontDeskTabs = [];
  function liveNavHtml(){return `<nav class="live-front-tabs" aria-label="Front Desk sections">${liveFrontDeskTabs.map(tab=>{const active=state.section===tab.id||tab.id==='checkout'&&state.section==='quicksale';return `<button type="button" class="live-front-tab ${active?'selected':''}" style="--tab-soft:${tab.soft};--tab-ink:${tab.ink};--tab-border:${tab.border}" data-action="nav" data-id="${tab.id}" aria-pressed="${active}"><img src="${tab.image}" alt="" width="48" height="48" draggable="false"><span>${tab.label}</span>${tab.id==='tickets'||tab.id==='checkout'?`<b class="live-tab-count">${activeTickets().length}</b>`:''}</button>`}).join('')}</nav>`}
  function shellHtml(){return '<div class="pos-content live-pos-content">'+(state.section==='completed'?completedSalesHtml():quickSaleHtml())+'</div>'}

  const ticketStatus = ticket => ticket.status || 'inservice';
  const activeTickets = () => state.tickets.filter(ticket=>!['paid','cancelled'].includes(ticketStatus(ticket)));
  const ticketServices = ticket => ticket.groups.flatMap(group=>group.services.map(service=>({tech:group.tech,service})));
  const ticketServiceName = service => service.name || baseCatalog.find(item=>item.id===service.id)?.name || 'Service';
  const ticketSubtotal = ticket => ticketServices(ticket).reduce((sum,{service})=>sum+Number(service.price ?? baseCatalog.find(item=>item.id===service.id)?.price ?? 0)+(service.addons||[]).reduce((extra,addon)=>extra+Number(typeof addon==='string'?(addonCatalog.find(item=>item.id===addon)?.price||0):(addon.price||0)),0),0);
  function floorTicketCard(ticket){const status=ticketStatus(ticket),selected=state.frontSelectedTicket===ticket.id,services=ticketServices(ticket);return `<article class="floor-ticket ${status} ${selected?'selected':''}"><button type="button" class="floor-ticket-select" data-action="front-select-ticket" data-id="${ticket.id}" aria-pressed="${selected}"><span class="floor-ticket-top"><b>#${ticket.id} · ${esc(ticket.name)}</b><span>${esc(ticket.arrivedAt||'Today')}</span></span><span class="floor-ticket-service">${esc(services.map(({service})=>ticketServiceName(service)).join(', ')||'Service to be assigned')}</span><span class="floor-ticket-foot">${esc([...new Set(ticket.groups.map(group=>group.tech).filter(Boolean))].join(' + ')||'No technician yet')}<strong>${money(ticketSubtotal(ticket))}</strong></span></button></article>`}
  const checkinStatus = ticket => ticketStatus(ticket)==='paid'?'Completed':ticketStatus(ticket)==='inservice'?'In Service':ticketStatus(ticket)==='ready'?'Ready to Pay':ticketStatus(ticket)==='cancelled'?'Cancelled':'Waiting';
  function visibleCheckins(){const term=state.frontCheckinSearch.trim().toLowerCase(),number=digits(term);return state.tickets.filter(ticket=>ticket.checkedIn).filter(ticket=>state.frontCheckinFilter==='all'||ticketStatus(ticket)===state.frontCheckinFilter).filter(ticket=>!term||ticket.name.toLowerCase().includes(term)||String(ticket.id).includes(term)||number&&digits(ticket.phone).includes(number))}
  function checkinRowsHtml(){const tickets=visibleCheckins();return tickets.length?tickets.map(ticket=>`<tr><td><strong>#${ticket.id}</strong></td><td>${esc(ticket.arrivedAt||'Today')}</td><td><strong>${esc(ticket.name)}</strong><small>${esc(maskPhone(ticket.phone))}</small></td><td><span class="checkin-type ${ticket.newGuest?'new':''}">${ticket.newGuest?'New guest':'Returning'}</span></td><td>${esc(ticket.checkInSource||'Front Desk')}</td><td>${esc(ticketServices(ticket).map(({service})=>ticketServiceName(service)).join(', ')||'—')}</td><td>${esc([...new Set(ticket.groups.map(group=>group.tech).filter(Boolean))].join(' + ')||'—')}</td><td><span class="checkin-status ${ticketStatus(ticket)}">${checkinStatus(ticket)}</span></td><td><button type="button" class="btn btn-secondary" data-action="front-checkin-detail" data-id="${ticket.id}">View detail</button></td></tr>`).join(''):`<tr><td colspan="9" class="checkin-empty">No check-ins match this view.</td></tr>`}
  function checkinSummaryHtml(){const checkins=state.tickets.filter(ticket=>ticket.checkedIn),average=checkins.length?Math.round(checkins.reduce((total,ticket)=>total+Number(ticket.waitMinutes||0),0)/checkins.length):0;return `<section class="checkin-summary" aria-label="Today's check-in summary"><div class="checkin-summary-label"><strong>Today's Check-in Overview</strong><span>Guest flow and new-customer acquisition · demo data</span></div><div class="floor-insight-grid checkin-metrics"><div><small>TOTAL CHECK-INS</small><strong>${checkins.length}</strong></div><div><small>NEW GUESTS</small><strong>${checkins.filter(ticket=>ticket.newGuest).length}</strong></div><div><small>RETURNING GUESTS</small><strong>${checkins.filter(ticket=>!ticket.newGuest).length}</strong></div><div><small>AVERAGE WAIT</small><strong>${average}m</strong></div></div></section>`}
  function checkinOverviewHtml(){const checkins=state.tickets.filter(ticket=>ticket.checkedIn),sources=Object.entries(checkins.reduce((result,ticket)=>{const source=ticket.checkInSource||'Front Desk';result[source]=(result[source]||0)+1;return result},{})),average=checkins.length?Math.round(checkins.reduce((total,ticket)=>total+Number(ticket.waitMinutes||0),0)/checkins.length):0,detail=checkins.find(ticket=>ticket.id===state.frontCheckinDetail),filters=[['all','All'],['waiting','Waiting'],['inservice','In Service'],['ready','Ready to Pay'],['paid','Completed'],['cancelled','Cancelled']];return `<section class="checkin-overview" aria-label="Check-in sources and history"><div class="checkin-overview-head"><div><p class="tech-screen-eyebrow">TODAY · CHECK-IN DETAIL</p><h3>Guest sources & check-ins</h3></div></div><div class="checkin-context"><div class="panel checkin-sources"><h4>Guest Sources</h4>${sources.length?sources.map(([source,count])=>`<div class="checkin-source"><span>${esc(source)}</span><div><i style="width:${Math.round(count/checkins.length*100)}%"></i></div><strong>${count}</strong></div>`).join(''):'<p>No check-ins yet today.</p>'}</div><div class="panel checkin-order"><h4>Guest Order Summary</h4><p>Each guest keeps their original check-in number through waiting, service, checkout, or cancellation.</p></div></div><div class="panel checkin-list"><div class="checkin-list-head"><h4>All Check-ins Today <span>${checkins.length}</span></h4></div><div class="checkin-controls" role="group" aria-label="Filter check-ins by status">${filters.map(([id,label])=>`<button type="button" class="${state.frontCheckinFilter===id?'selected':''}" data-action="front-checkin-filter" data-value="${id}" aria-pressed="${state.frontCheckinFilter===id}">${label}</button>`).join('')}<label class="checkin-search"><span class="sr-only">Search check-ins</span><input class="input" id="front-checkin-search" type="search" placeholder="Search name, phone, or #" value="${esc(state.frontCheckinSearch)}"></label></div><div class="checkin-table-wrap"><table class="checkin-table"><thead><tr><th>#</th><th>Time</th><th>Customer</th><th>Type</th><th>Source</th><th>Service</th><th>Technician</th><th>Status</th><th></th></tr></thead><tbody id="front-checkin-rows">${checkinRowsHtml()}</tbody></table></div>${detail?`<div class="checkin-detail"><div><small>CHECK-IN #${detail.id}</small><strong>${esc(detail.name)}</strong><span>${esc(maskPhone(detail.phone))} · ${esc(detail.arrivedAt||'Today')} · ${esc(detail.checkInSource||'Front Desk')}</span></div><div><small>SERVICE & TEAM</small><strong>${esc(ticketServices(detail).map(({service})=>ticketServiceName(service)).join(', ')||'Not assigned')}</strong><span>${esc([...new Set(detail.groups.map(group=>group.tech).filter(Boolean))].join(' + ')||'No technician')} · ${checkinStatus(detail)}</span></div><button type="button" class="btn btn-secondary" data-action="front-checkin-detail" data-id="${detail.id}">Close</button></div>`:''}</div></section>`}
  function overviewHtml(){
    const active=activeTickets(),selected=active.find(ticket=>ticket.id===state.frontSelectedTicket)||active[0],selectedTech=state.selectedTech;if(selected)state.frontSelectedTicket=selected.id;
    const lanes=[['waiting','Waiting','Assign a technician'],['inservice','In service','Track work in progress'],['ready','Ready to pay','Finish checkout']];
    const search=state.frontSearchResult;
    return `<section class="floor-head"><div><p class="tech-screen-eyebrow">FRONT DESK · TODAY</p><h2>Today's Operations</h2><p>Track waiting guests, services in progress, and checkout.</p></div><span class="floor-demo">● Prototype example</span></section>
      ${checkinSummaryHtml()}
      <div class="floor-command panel"><div class="floor-search"><label for="front-search">Find a customer or ticket</label><div><input id="front-search" class="input" inputmode="search" autocomplete="off" placeholder="Phone, name, or ticket #" value="${esc(state.frontSearch)}"><button type="button" class="btn btn-secondary" data-action="front-search">Find</button></div></div><div class="floor-command-actions"><button type="button" class="btn btn-secondary" data-action="front-arrival-toggle">${icon('user')} Guest arrival</button><button type="button" class="btn btn-primary" data-action="new-checkout">${icon('plus')} Direct checkout</button></div></div>
      ${state.frontSearchNotice?`<p class="floor-message" role="status">${esc(state.frontSearchNotice)}</p>`:''}
      ${search?`<div class="floor-search-result panel"><div><small>${search.ticketId?'OPEN TICKET':search.name?'RETURNING CUSTOMER':'NEW CUSTOMER'}</small><strong>${esc(search.name||'New customer')}${search.ticketId?` · #${search.ticketId}`:''}</strong><span>${search.phone?esc(maskPhone(search.phone)):'Search by name or ticket'}</span></div><button type="button" class="btn btn-secondary" data-action="${search.ticketId?'front-search-open':'front-search-start'}">${search.ticketId?'Open ticket':'Start checkout'}</button></div>`:''}
      ${state.frontArrivalOpen?`<section class="floor-arrival panel"><div class="floor-arrival-head"><div><strong>Guest arrival</strong><p>Look up the guest by phone, then add them to the waiting list.</p></div><button type="button" class="floor-close" data-action="front-arrival-toggle" aria-label="Close arrival form">×</button></div><div class="floor-arrival-fields"><div><label for="front-arrival-phone">Phone number · required</label><input id="front-arrival-phone" class="input" inputmode="tel" autocomplete="off" placeholder="(000) 000-0000" value="${esc(state.frontArrivalPhone)}"></div><button type="button" class="btn btn-secondary" data-action="front-arrival-lookup">Find guest</button>${state.frontArrivalStatus==='new'?`<div><label for="front-arrival-name">New guest name · required</label><input id="front-arrival-name" class="input" autocomplete="off" placeholder="Guest name" value="${esc(state.frontArrivalName)}"></div>`:''}${state.frontArrivalStatus==='existing'?`<div class="floor-arrival-found"><small>RETURNING GUEST</small><strong>${esc(state.frontArrivalName)}</strong></div>`:''}${state.frontArrivalStatus!=='idle'?`<button type="button" class="btn btn-primary" data-action="front-arrival-create">Add to waiting</button>`:''}</div><p class="floor-message" role="status">${esc(state.frontArrivalNotice)}</p></section>`:''}
      <div class="floor-mobile-tabs" role="group" aria-label="Guest status">${lanes.map(([id,label])=>`<button type="button" data-action="front-lane" data-value="${id}" class="${state.frontLane===id?'selected':''}" aria-pressed="${state.frontLane===id}">${label} <b>${active.filter(ticket=>ticketStatus(ticket)===id).length}</b></button>`).join('')}</div>
      <div class="floor-layout"><div class="floor-lanes">${lanes.map(([id,label,description])=>{const tickets=active.filter(ticket=>ticketStatus(ticket)===id);return `<section class="floor-lane ${id} ${state.frontLane===id?'mobile-selected':''}" aria-label="${label}"><div class="floor-lane-head"><div><span class="floor-status-dot"></span><strong>${label}</strong><small>${description}</small></div><b>${tickets.length}</b></div><div class="floor-lane-list">${tickets.length?tickets.map(floorTicketCard).join(''):'<p class="floor-empty">No guests in this step.</p>'}</div></section>`}).join('')}</div>
      <aside class="floor-side"><section class="panel floor-tech-panel"><div class="floor-panel-head"><div><small>STAFF STATUS</small><h3>Technicians</h3></div><button type="button" data-action="nav" data-id="technicians">View all →</button></div><div class="floor-tech-list">${techs.map(tech=>{const jobs=active.filter(ticket=>ticketStatus(ticket)==='inservice').flatMap(ticket=>ticketServices(ticket).filter(({tech:lead,service})=>lead===tech||service.coTech===tech));const busy=jobs.length>0;return `<button type="button" class="floor-tech ${state.selectedTech===tech?'selected':''}" data-action="front-select-tech" data-id="${esc(tech)}" aria-pressed="${state.selectedTech===tech}"><span class="floor-tech-avatar">${esc(tech.split(' ').map(part=>part[0]).join('').slice(0,2))}</span><span><strong>${esc(tech)}</strong><small>${busy?`${jobs.length} service${jobs.length===1?'':'s'}`:'Ready for work'}</small></span><em class="${busy?'busy':'available'}">${busy?'Working':'Available'}</em></button>`}).join('')}</div><div class="floor-tech-actions"><button type="button" class="btn btn-secondary" data-action="front-tech-new">New ticket with ${esc(selectedTech)}</button><button type="button" class="btn btn-primary" data-action="front-tech-assign" ${selected?'':'disabled'}>Assign to selected guest</button></div></section>
      <section class="panel floor-detail"><div class="floor-panel-head"><div><small>SELECTED GUEST</small><h3>${selected?esc(selected.name):'Choose a guest'}</h3></div>${selected?`<span class="floor-detail-number">#${selected.id}</span>`:''}</div>${selected?`<p class="floor-detail-meta">${esc(maskPhone(selected.phone))} · Arrived ${esc(selected.arrivedAt||'today')}</p><div class="floor-detail-work">${ticketServices(selected).length?ticketServices(selected).map(({tech,service})=>`<div><span>${esc(ticketServiceName(service))}<small>${esc(tech)}${service.coTech?` + ${esc(service.coTech)}`:''}</small></span><strong>${money(service.price ?? baseCatalog.find(item=>item.id===service.id)?.price ?? 0)}</strong></div>`).join(''):'<p>No service assigned yet.</p>'}</div><div class="floor-detail-total"><span>Service estimate</span><strong>${money(ticketSubtotal(selected))}</strong></div><div class="floor-detail-actions">${ticketStatus(selected)==='waiting'?`<button type="button" class="btn btn-primary" data-action="front-tech-assign">Assign technician & service</button>`:''}${ticketStatus(selected)==='inservice'?`<button type="button" class="btn btn-secondary" data-action="front-status" data-value="ready" data-id="${selected.id}">Mark ready to pay</button>`:''}${ticketStatus(selected)==='ready'?`<button type="button" class="btn btn-secondary" data-action="front-status" data-value="inservice" data-id="${selected.id}">Back to service</button>`:''}<button type="button" class="btn ${ticketStatus(selected)==='ready'?'btn-primary':'btn-secondary'}" data-action="open-ticket" data-id="${selected.id}">Open checkout →</button></div>`:'<p class="floor-empty">Select a guest from the board to see their ticket.</p>'}</section></aside></div>
      ${checkinOverviewHtml()}
      <p class="tech-prototype-note">Demo data only. Arrival, status, assignments, and checkout stay in this browser session. No live Nexora record is changed.</p>`;
  }
  function checkoutHtml(){return `<section class="checkout-hero"><div><div class="hero-kicker">${icon('card')} Payment workspace</div><h2>Checkout Customer</h2><p class="hero-copy">Look up the guest by phone, then assign work by technician. Check-in is optional.</p></div><div class="hero-actions"><span class="count-chip">${activeTickets().length} open tickets</span><button type="button" class="btn btn-secondary" data-action="nav" data-id="quicksale">Products &amp; Other Sales</button><button type="button" class="btn btn-primary" data-action="new-checkout">${icon('plus')} New checkout</button></div></section><div class="list-heading"><div><h3>Open customer tickets</h3><p class="muted">Existing tickets remain one tap away.</p></div></div><div class="ticket-grid">${orderedWorkspace('tickets',activeTickets(),t=>t.id).map((t,index,ordered)=>`<article class="ticket-card panel"><div class="ticket-top"><div><span class="ticket-id">TICKET #${t.id}</span><h4 class="ticket-name">${esc(t.name)}</h4></div><span class="status">${ticketStatus(t)==='waiting'?'Waiting':ticketStatus(t)==='ready'?'Ready to pay':'In service'}</span></div><div class="ticket-details"><div class="field-label">Services</div><p>${esc(t.groups.flatMap(g=>g.services.map(s=>baseCatalog.find(c=>c.id===s.id)?.name||s.name||'Custom service')).join(', '))}</p><div class="field-label">Technician</div><p>${esc(t.groups.map(g=>g.tech).join(', '))}</p></div><div class="ticket-actions"><button type="button" class="btn btn-secondary btn-wide" data-action="open-ticket" data-id="${t.id}">${icon('card')} Checkout</button><button type="button" class="btn btn-secondary ticket-cancel" data-action="request-cancel-ticket" data-id="${t.id}" aria-label="Cancel ticket #${t.id} for ${esc(t.name)}">Cancel ticket</button></div>${reorderControls('tickets',String(t.id),`ticket ${t.id}`,index,ordered.length)}</article>`).join('')||'<p class="panel ticket-empty">No open tickets. Start a new checkout when the next guest is ready.</p>'}</div>`}
  function ticketWorkForTech(tech){return activeTickets().filter(ticket=>ticketStatus(ticket)==='inservice').flatMap(ticket=>ticket.groups.flatMap(group=>group.services.filter(service=>group.tech===tech||service.coTech===tech).map(service=>({ticket,service,role:group.tech===tech?'lead':'with '+group.tech}))))}
  function catalogChoices(category){return fullCatalog.map((item,index)=>({item,index})).filter(({item})=>item.category===category)}
  function technicianGuestResultHtml(){if(state.techNewStatus==='existing')return `<div class="tech-guest-result found"><strong>Returning customer: ${esc(state.techNewName)}</strong><span>Name loaded from phone lookup.</span></div>`;if(state.techNewStatus==='new')return `<div class="tech-guest-result new"><strong>New customer</strong><span>Enter their name before creating the ticket.</span><label for="tech-guest-name">Customer name · required</label><input class="input" id="tech-guest-name" autocomplete="off" value="${esc(state.techNewName)}" placeholder="First and last name"></div>`;return `<p class="hint">Demo lookup: 202-555-0101 is a returning customer; another phone creates a new customer.</p>`}
  function techNewTicketHtml(categories){const service=state.techNewServiceIndex!==''?fullCatalog[Number(state.techNewServiceIndex)]:null;return `<div class="tech-flow-steps"><span><b>1</b> Customer</span><span><b>2</b> Service & team</span><span><b>3</b> Ticket or checkout</span></div><div class="tech-flow-grid"><div class="tech-flow-section"><h4>Customer</h4><label for="tech-guest-phone">Phone number · required</label><div class="tech-phone-row"><input class="input" id="tech-guest-phone" inputmode="tel" autocomplete="off" value="${esc(state.techNewPhone)}" placeholder="(000) 000-0000"><button type="button" class="btn btn-secondary" data-action="tech-lookup-guest">Find customer</button></div><div id="tech-guest-result" aria-live="polite">${technicianGuestResultHtml()}</div></div><div class="tech-flow-section"><h4>Service by ${esc(state.selectedTech)}</h4><div class="tech-field-pair"><div class="form-field"><label for="tech-new-category">Category</label><select class="select" id="tech-new-category">${categories.map(category=>`<option value="${esc(category)}" ${state.techNewCategory===category?'selected':''}>${esc(category)}</option>`).join('')}</select></div><div class="form-field"><label for="tech-new-service">Service</label><select class="select" id="tech-new-service"><option value="">Choose service</option>${catalogChoices(state.techNewCategory).map(({item,index})=>`<option value="${index}" ${String(state.techNewServiceIndex)===String(index)?'selected':''}>${esc(item.name)} · ${money(item.price)}</option>`).join('')}</select></div></div><div class="form-field"><label for="tech-co-worker">Working together with</label><select class="select" id="tech-co-worker"><option value="">No second technician</option>${techs.filter(tech=>tech!==state.selectedTech).map(tech=>`<option value="${esc(tech)}" ${state.techCoTech===tech?'selected':''}>${esc(tech)} · same service</option>`).join('')}</select><p class="hint">A shared service is charged once. Both technicians appear on the ticket and in tip allocation.</p></div></div></div><div class="tech-checkout-footer"><div class="tech-new-preview"><div><small>TICKET PREVIEW</small><strong id="tech-guest-preview">${esc(state.techNewName||'Customer not selected')}</strong><span>${esc(state.selectedTech)}${state.techCoTech?` + ${esc(state.techCoTech)}`:''}</span></div><div><strong>${service?esc(service.name):'Choose a service'}</strong><b>${service?money(service.price):'$0.00'}</b></div></div><div class="tech-checkout-actions"><p class="tech-assign-feedback" role="status">${esc(state.techNewNotice)}</p><div class="tech-new-actions"><button type="button" class="btn btn-secondary" data-action="tech-create-ticket">Create ticket</button><button type="button" class="btn btn-primary" data-action="tech-create-checkout">Create ticket & checkout →</button></div><p class="tech-prototype-note">No check-in is required. Discounts, add-ons, tip, and payment choice remain editable at checkout.</p></div></div>`}
  function techExistingTicketHtml(categories){const available=catalogChoices(state.assignCategory);return `<div class="tech-assign-title"><span class="tech-panel-kicker">EXISTING TICKET</span><h3>Assign another service to ${esc(state.selectedTech)}</h3><p>Choose an open ticket and a service. It will appear under this technician at checkout.</p></div><div class="tech-assign-fields"><div class="form-field"><label for="assign-ticket">Customer ticket</label><select class="select" id="assign-ticket"><option value="">Choose open ticket</option>${activeTickets().map(ticket=>`<option value="${ticket.id}" ${String(state.assignTicketId)===String(ticket.id)?'selected':''}>#${ticket.id} · ${esc(ticket.name)}</option>`).join('')}</select></div><div class="form-field"><label for="assign-category">Service category</label><select class="select" id="assign-category">${categories.map(category=>`<option value="${esc(category)}" ${state.assignCategory===category?'selected':''}>${esc(category)}</option>`).join('')}</select></div><div class="form-field"><label for="assign-service">Salon service</label><select class="select" id="assign-service"><option value="">Choose service</option>${available.map(({item,index})=>`<option value="${index}" ${String(state.assignServiceIndex)===String(index)?'selected':''}>${esc(item.name)} · ${money(item.price)}</option>`).join('')}</select></div></div><div class="tech-assign-footer"><button type="button" class="btn btn-primary" data-action="assign-tech-service">${icon('plus')} Assign to ${esc(state.selectedTech)}</button><p class="tech-assign-note">Uses the salon's standard menu price. Add-ons and discounts can be edited on the checkout ticket.</p></div><p class="tech-assign-feedback" role="status">${esc(state.assignmentNotice)}</p>`}
  function techniciansHtml(){const categories=[...new Set(fullCatalog.map(item=>item.category))],work=ticketWorkForTech(state.selectedTech),busy=techs.filter(tech=>ticketWorkForTech(tech).length).length;return `<section class="tech-screen-head"><div><p class="tech-screen-eyebrow">FRONT DESK · STAFF WORKSPACE</p><h2>Salon Technicians</h2><p class="muted">Tap a technician to assign work, make a ticket, or start checkout for a customer.</p></div><div class="tech-head-actions"><span class="tech-count">${busy} working · ${techs.length-busy} available</span></div></section><div class="tech-roster" role="group" aria-label="Select technician">${orderedWorkspace('techs',techs,tech=>tech).map((tech,index,ordered)=>{const jobs=ticketWorkForTech(tech),selected=state.selectedTech===tech;return `<div class="tech-roster-item"><button type="button" class="tech-roster-card ${selected?'selected':''}" data-action="select-tech" data-id="${esc(tech)}" aria-pressed="${selected}"><span class="tech-avatar">${esc(tech.split(' ').map(part=>part[0]).join('').slice(0,2))}</span><span class="tech-card-copy"><strong>${esc(tech)}</strong><small>${jobs.length?`${jobs.length} assigned service${jobs.length===1?'':'s'}`:'Ready for work'}</small></span><span class="tech-status ${jobs.length?'busy':'available'}">${jobs.length?'Working':'Available'}</span></button>${reorderControls('techs',tech,tech,index,ordered.length)}</div>`}).join('')}</div><div class="tech-workspace"><section class="panel tech-current"><div class="tech-panel-head"><div><span class="tech-panel-kicker">SELECTED TECHNICIAN</span><h3>${esc(state.selectedTech)}</h3><p>${work.length} service${work.length===1?'':'s'} assigned on open tickets</p></div><span class="tech-panel-icon">${icon('users')}</span></div>${work.length?`<div class="tech-work-list">${work.map(({ticket,service,role})=>`<div class="tech-work-row"><div><strong>${esc(service.name||baseCatalog.find(c=>c.id===service.id)?.name||'Service')}</strong><span>Ticket #${ticket.id} · ${esc(ticket.name)}${role==='lead'?'':` · ${esc(role)}`}</span></div><button type="button" class="tech-ticket-link" data-action="open-ticket" data-id="${ticket.id}">Open ticket →</button></div>`).join('')}</div>`:`<div class="tech-empty">No services assigned yet. Start a ticket for this technician.</div>`}</section><section class="panel tech-assign"><div class="tech-mode-tabs" role="group" aria-label="Technician work mode"><button type="button" class="${state.techMode==='new'?'selected':''}" data-action="tech-mode" data-value="new" aria-pressed="${state.techMode==='new'}">New ticket & checkout</button><button type="button" class="${state.techMode==='existing'?'selected':''}" data-action="tech-mode" data-value="existing" aria-pressed="${state.techMode==='existing'}">Add to existing ticket</button></div>${state.techMode==='new'?techNewTicketHtml(categories):techExistingTicketHtml(categories)}</section></div><p class="tech-prototype-note">Prototype data only. No live technician schedule, customer, ticket, or payment is changed.</p>`}
  function customerHistoryHtml(){return `<section class="history-head"><div><p class="tech-screen-eyebrow">FRONT DESK · CUSTOMER HISTORY</p><h2>Customer History</h2><p>Names and visit summaries support service. Contact details and private notes require a separate approval.</p></div><span class="count-chip">${state.tickets.length} demo customers</span></section><div class="history-grid">${state.tickets.map(ticket=>{const shown=contactVisible(ticket.phone),notes=notesVisible(ticket.phone);return `<article class="panel history-card"><div class="history-card-top"><div><span>Customer · ticket #${ticket.id}</span><h3>${esc(ticket.name)}</h3></div><span class="history-lock">${shown||notes?'Approved view':'Protected'}</span></div><p><b>Last visit</b> · Service ticket #${ticket.id}</p><div class="history-sensitive"><div><span>Phone</span><strong class="sensitive-phone">${esc(displayPhone(ticket.phone))}</strong></div><div><span>Email</span><strong>${esc(displayEmail(ticket.phone))}</strong></div><div><span>Private note</span><strong>${notes?'Demo note: prefers quiet appointments.':'Restricted · approval required'}</strong></div></div><div class="history-actions"><button type="button" class="btn btn-secondary" data-action="request-sensitive" data-type="reveal-contact" data-id="${ticket.id}">${shown?'Renew contact access':'View full contact'}</button><button type="button" class="btn btn-secondary" data-action="request-sensitive" data-type="view-notes" data-id="${ticket.id}">${notes?'Renew note access':'View private note'}</button>${shown||notes?`<button type="button" class="btn btn-secondary" data-action="hide-sensitive" data-type="all" data-id="${ticket.id}">Hide</button>`:''}</div></article>`}).join('')}</div><p class="tech-prototype-note">Demo records only. Production must enforce permission on every API response, search result, printout, and export.</p>`}

  const retailCatalog=[
    {id:'cuticle-oil',name:'Cuticle Oil',sku:'RET-001',price:12},
    {id:'hand-lotion',name:'Hand Lotion',sku:'RET-002',price:18},
    {id:'nail-care-kit',name:'Nail Care Kit',sku:'RET-003',price:24}
  ];
  const newSaleLine=()=>({uid:uid(),type:'product',catalogId:'cuticle-oil',description:'Cuticle Oil',sku:'RET-001',quantity:1,unitPrice:12,providerType:'salon',providerName:'',helperName:''});
  const newQuickSale=()=>({giftCardCode:'',phone:'',customerName:'',customerStatus:'idle',lines:[newSaleLine()],discount:0,tip:0,tipAllocationMode:'proportional',tipSplits:{},payment:acceptedPaymentMethods().find(([id])=>id!=='split')?.[0]||'cash',paymentMoreOpen:false,creditPortion:0,splitOtherMethod:splitAlternatives()[0]?.[0]||'cash',walletRequest:null,notice:''});
  const saleDraft=()=>state.quickSale||(state.quickSale=newQuickSale());
  const saleLine=l=>Math.round((Math.max(0,Number(l.quantity)||0)*Math.max(0,Number(l.unitPrice)||0))*100)/100;
  const saleSubtotal=()=>saleDraft().lines.reduce((sum,l)=>sum+saleLine(l),0);
  const saleDue=()=>Math.max(0,Math.round((saleSubtotal()-Math.max(0,Number(saleDraft().discount)||0))*100)/100);
  const saleCardBase=(method=saleDraft().payment)=>method==='credit'?saleDue():method==='split'?Math.max(0,Math.min(saleDue(),Number(saleDraft().creditPortion)||0)):0;
  const saleWalletAmount = () => saleDraft().payment==='vlinkpay'?saleTotal():saleDraft().payment==='split'&&saleDraft().splitOtherMethod==='vlinkpay'?Math.max(0,cents(saleTotal()-saleCardBase('split')+methodDiscount('credit',saleCardBase('split'))-saleFee('split')-Number(saleDraft().splitCashPortion||0))/100):0;
  const saleWalletKey = () => {const d=saleDraft();return walletRequestKey(d.phone,saleWalletAmount(),d.payment,d.splitOtherMethod,JSON.stringify([d.customerName,d.discount,d.tip,d.splitCashPortion,d.lines.map(l=>[l.uid,l.type,l.catalogId,l.description,l.quantity,l.unitPrice,l.providerType,l.providerName,l.helperName])]))};
  const saleWalletConfirmed = () => !customerWalletSelected(saleDraft().payment,saleDraft().splitOtherMethod)||cents(saleWalletAmount())===0||saleDraft().walletRequest?.key===saleWalletKey()&&saleDraft().walletRequest.status==='confirmed';
  const saleWalletPanelHtml = () => customerWalletPanelHtml('sale',customerWalletSelected(saleDraft().payment,saleDraft().splitOtherMethod)?saleWalletAmount():null,saleDraft().walletRequest,saleWalletKey());
  const saleWalletBase=(method=saleDraft().payment)=>method==='split'?(walletEligible(saleDraft().splitOtherMethod)?Math.max(0,saleDue()-saleCardBase('split')):0):(walletEligible(method)?saleDue():0);
  const saleFee=(method=saleDraft().payment)=>Math.round(Math.max(0,saleCardBase(method)-methodDiscount('credit',saleCardBase(method)))*(state.cardFeeEnabled?state.cardFeePercent:0))/100;
  const saleWalletDiscount=(method=saleDraft().payment)=>method==='split'?methodDiscount('credit',saleCardBase('split'))+methodDiscount(saleDraft().splitOtherMethod,Math.max(0,saleDue()-saleCardBase('split')-(saleDraft().splitOtherMethod==='cash'?0:Number(saleDraft().splitCashPortion||0)))):methodDiscount(method,saleDue());
  const saleTotal=(method=saleDraft().payment)=>Math.round((saleDue()-saleWalletDiscount(method)+saleFee(method)+Math.max(0,Number(saleDraft().tip)||0))*100)/100;
  const saleProviderLabel=l=>l.type==='product'?'Retail sale · '+roleLabel(state.authRole):l.providerType==='staff'?l.providerName+' · salon technician':l.providerType==='manager'?l.providerName+' · manager':l.providerType==='visiting'?l.providerName+' · visiting technician':l.providerType==='helper'?l.providerName+' · guest helper':'Salon / house';
  function saleLineHtml(l,index){return `<div class="sale-line panel"><div class="sale-line-top"><strong>Item ${index+1}</strong><button class="text-button danger-text" type="button" data-action="sale-remove-line" data-id="${l.uid}">Remove</button></div><div class="sale-fields"><label>Charge type<select class="select" data-sale-field="type" data-id="${l.uid}"><option value="product" ${l.type==='product'?'selected':''}>Retail product</option><option value="service" ${l.type==='service'?'selected':''}>Service</option><option value="other" ${l.type==='other'?'selected':''}>Other charge</option></select></label>${l.type==='product'?`<label>Product<select class="select" data-sale-field="catalogId" data-id="${l.uid}">${retailCatalog.map(x=>`<option value="${x.id}" ${l.catalogId===x.id?'selected':''}>${esc(x.name)} · ${esc(x.sku)}</option>`).join('')}</select></label>`:`<label>Description<input class="input" data-sale-field="description" data-id="${l.uid}" value="${esc(l.description)}" placeholder="What was sold or performed?"></label>`}<label>Qty<input class="input" type="number" min="1" step="1" data-sale-field="quantity" data-id="${l.uid}" value="${l.quantity}"></label><label>Unit price ($)<input class="input" type="number" min="0" step="0.01" data-sale-field="unitPrice" data-id="${l.uid}" value="${l.unitPrice}"></label></div>${l.type==='service'||l.type==='other'?`<div class="sale-provider"><div class="sale-fields"><label>Who did the work?<select class="select" data-sale-field="providerType" data-id="${l.uid}"><option value="staff" ${l.providerType==='staff'?'selected':''}>Salon technician</option><option value="manager" ${l.providerType==='manager'?'selected':''}>Owner / manager</option><option value="visiting" ${l.providerType==='visiting'?'selected':''}>Visiting technician</option><option value="helper" ${l.providerType==='helper'?'selected':''}>Guest helper / friend</option><option value="salon" ${l.providerType==='salon'?'selected':''}>Salon / house charge</option></select></label>${l.providerType==='staff'?`<label>Technician<select class="select" data-sale-field="providerName" data-id="${l.uid}"><option value="">Select technician</option>${techs.map(t=>`<option value="${esc(t)}" ${l.providerName===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`:l.providerType==='salon'?'':`<label>Full name<input class="input" data-sale-field="providerName" data-id="${l.uid}" value="${esc(l.providerName)}" placeholder="Name for receipt and audit"></label>`}</div>${l.type==='service'?`<label>Assisting person (optional)<input class="input" data-sale-field="helperName" data-id="${l.uid}" value="${esc(l.helperName)}" placeholder="Who helped with this service?"></label>`:''}<p class="hint">The performer and assistant are saved on this line. Visiting workers and helpers are not automatically added to salon payroll.</p></div>`:''}<div class="sale-line-total">Line total <strong>${money(saleLine(l))}</strong></div></div>`}
  function quickSaleHtml(){const d=saleDraft();return `<section class="checkout-frame panel sale-frame"><div class="builder-head"><div><p class="eyebrow">FRONT DESK · FLEXIBLE SALE</p><h2>Products & Other Sales</h2><p class="muted">Create a retail-only, service-only, or mixed ticket. Record who did each service and who helped.</p></div><span class="direct-note">No check-in required</span></div><div class="checkout-progress"><span><b>1</b> Customer</span><span><b>2</b> Items & people</span><span><b>3</b> Payment & save</span></div><div class="sale-grid"><div class="stack"><section class="panel form-panel"><h3 class="panel-title"><span class="step">1</span> Customer</h3><label>Customer phone · required</label><div class="lookup-row"><input class="input" id="sale-phone" type="tel" inputmode="tel" autocomplete="tel-national" value="${esc(d.customerStatus==='existing'?displayPhone(d.phone):formatPhone(d.phone))}" placeholder="(000) 000-0000"><button class="btn btn-secondary" type="button" data-action="sale-lookup">Find customer</button></div>${d.customerStatus==='existing'?`<div class="identity-card found"><b>Existing customer found</b><strong>${esc(d.customerName)}</strong><span>${esc(displayPhone(d.phone))}</span></div>`:d.customerStatus==='new'?`<div class="identity-card"><b>New customer</b><p>Enter their name to save this sale.</p><input class="input" id="sale-customer-name" value="${esc(d.customerName)}" placeholder="Customer name"></div>`:''}</section><section class="panel form-panel"><h3 class="panel-title"><span class="step">2</span> Items & people</h3><p class="hint">Select product, service, or other charge for each line. An assistant is recorded separately from the primary performer.</p><div class="sale-lines">${d.lines.map(saleLineHtml).join('')}</div><button class="add-tech" type="button" data-action="sale-add-line">+ Add product, service, or charge</button></section></div><aside class="summary-panel live-payment-sidebar ticket-workspace tw-staging" aria-label="Payment & save"><div id="sale-payment-content">${salePaymentHtml()}</div></aside></div></section>`}
  function saleParticipants(){const result=new Map();for(const l of saleDraft().lines){if(l.type==='product')continue;if(l.providerType!=='salon'&&l.providerName.trim()){const name=l.providerName.trim(),item=result.get(name)||{name,type:l.providerType,workCents:0};item.workCents+=cents(saleLine(l));result.set(name,item)}if(l.type==='service'&&l.helperName.trim()){const name=l.helperName.trim(),item=result.get(name)||{name,type:'helper',workCents:0};result.set(name,item)}}return [...result.values()]}
  function saleTipAllocation(){const participants=saleParticipants(),mode=saleDraft().tipAllocationMode,result=Object.fromEntries(participants.map(p=>[p.name,0])),totalCents=cents(saleDraft().tip);if(!participants.length)return result;if(mode==='manual'){participants.forEach(p=>result[p.name]=cents(saleDraft().tipSplits[p.name]));return result}const workTotal=participants.reduce((sum,p)=>sum+p.workCents,0),weights=participants.map(p=>mode==='proportional'&&workTotal?p.workCents:1),weightTotal=weights.reduce((a,b)=>a+b,0);const shares=participants.map((p,index)=>({name:p.name,index,exact:totalCents*weights[index]/weightTotal}));let remaining=totalCents;shares.forEach(share=>{result[share.name]=Math.floor(share.exact);remaining-=result[share.name]});shares.sort((a,b)=>(b.exact-Math.floor(b.exact))-(a.exact-Math.floor(a.exact))||a.index-b.index);for(let i=0;i<remaining;i++)result[shares[i].name]++;return result}
  function saleTipAllocationHtml(){const d=saleDraft(),people=saleParticipants(),allocation=saleTipAllocation();if(!Number(d.tip))return '';return `<div class="sale-tip-split"><p class="summary-title">Tip allocation</p><div class="tip-split-modes">${[['proportional','By work'],['equal','Equal'],['fifty','50 / 50'],['manual','Manual']].map(([id,label])=>`<button type="button" data-action="sale-tip-mode" data-value="${id}" class="${d.tipAllocationMode===id?'selected':''}" ${id==='fifty'&&people.length!==2?'disabled':''}>${label}</button>`).join('')}</div>${people.map(p=>`<div class="tip-split-row"><span>${esc(p.name)}<small>${esc(p.type)} · ${money(p.workCents/100)} work</small></span>${d.tipAllocationMode==='manual'?`<input class="input" type="number" min="0" step="0.01" data-sale-tip-person="${esc(p.name)}" value="${Number(d.tipSplits[p.name]||0)}">`:`<strong>${money((allocation[p.name]||0)/100)}</strong>`}</div>`).join('')}<p class="hint">${d.tipAllocationMode==='proportional'?'By work credits the primary performer; use Manual to give part of the tip to a helper.':'Tip shares are saved on the receipt.'}</p></div>`}
  const saleGiftNeeded=()=>saleDraft().payment==='gift'?saleTotal():saleDraft().payment==='split'&&saleDraft().splitOtherMethod==='gift'?Math.max(0,Math.round((saleTotal()-saleCardBase('split')+methodDiscount('credit',saleCardBase('split'))-saleFee()-Number(saleDraft().splitCashPortion||0))*100)/100):0;
  function liveSaleSettings(){const d=saleDraft();if(d.receiptChoice===undefined)d.receiptChoice='none';if(d.cashReceived===undefined)d.cashReceived='';return d}
  function liveSaleItemsHtml(){
    const groups=new Map();
    saleDraft().lines.forEach(line=>{
      const label=line.type==='service'&&line.providerType==='staff'&&line.providerName.trim()?'Tech. '+line.providerName.trim():saleProviderLabel(line);
      if(!groups.has(label))groups.set(label,[]);
      groups.get(label).push(line);
    });
    return [...groups].map(([label,lines])=>`<section class="tw-summary-tech"><div class="tw-summary-tech-head"><strong>${esc(label)}</strong><span>${lines.length} items · ${money(lines.reduce((sum,line)=>sum+saleLine(line),0))}</span></div><ul>${lines.map(line=>`<li><span>${esc(line.description||'Unspecified item')}${Number(line.quantity)>1?' × '+line.quantity:''}${line.type==='service'&&line.helperName?'<small class="live-summary-assistant">Assisted by '+esc(line.helperName)+'</small>':''}</span><strong>${money(saleLine(line))}</strong><button type="button" class="tw-button tw-summary-remove tw-red" data-action="sale-remove-line" data-id="${line.uid}" aria-label="Remove ${esc(line.description||'Unspecified item')}">×</button></li>`).join('')}</ul></section>`).join('');
  }
  function salePercentOff(amount,base){return Number((base>0?Math.min(base,amount)/base*100:0).toFixed(2)).toLocaleString('en-US')+'% off'}
  function liveCashFeedback(){
    const d=liveSaleSettings();
    if(!String(d.cashReceived).trim())return '<span>Change due <strong>$0.00</strong></span>';
    const received=Number(d.cashReceived)||0,difference=Math.abs(received-saleTotal()),covered=received>=saleTotal();
    return `<span class="${covered?'':'short'}">${covered?'Change due':'Amount remaining'} <strong>${money(difference)}</strong></span>`;
  }
