  function validateSale(){const d=saleDraft();if(liveCashShort())return 'Cash received must cover the total amount.';if(digits(d.phone).length!==10||!['existing','new'].includes(d.customerStatus))return 'Find the customer using a 10-digit phone number.';if(!d.customerName.trim())return 'Enter the customer name.';if(!d.lines.length)return 'Add at least one item.';for(const l of d.lines){if(!l.description.trim())return 'Enter a description for every item.';if(!Number.isInteger(Number(l.quantity))||Number(l.quantity)<1)return 'Quantity must be a whole number of at least one.';if(!Number.isFinite(Number(l.unitPrice))||Number(l.unitPrice)<0)return 'Enter a valid unit price.';if(l.type!=='product'&&l.providerType!=='salon'&&!l.providerName.trim())return 'Name the person who performed each service or charge.';if(l.type==='service'&&l.helperName.trim()&&l.helperName.trim()===l.providerName.trim())return 'The assistant must be a different person from the performer.'}if(Number(d.discount)<0||Number(d.discount)>saleSubtotal())return 'Discount cannot exceed the items subtotal.';if(d.payment==='split'&&(Number(d.creditPortion)<=0||Number(d.creditPortion)>=saleDue()))return 'Enter a card portion between $0 and the item subtotal.';if(d.payment==='split'&&(!Number.isFinite(Number(d.splitCashPortion))||Number(d.splitCashPortion)<0||d.splitOtherMethod==='cash'&&Number(d.splitCashPortion)>0||Number(d.splitCashPortion)>=saleDue()-saleCardBase('split')))return 'Cash portion must leave a positive amount for the other method.';if(Number(d.tip)<0||!Number.isFinite(Number(d.tip)))return 'Enter a valid tip.';if(Number(d.tip)>0&&!d.lines.some(l=>l.type!=='product'&&l.providerType!=='salon'))return 'Choose a named service performer before adding a tip.';if(d.tipAllocationMode==='fifty'&&saleParticipants().length!==2)return '50 / 50 requires exactly two named people.';if(d.tipAllocationMode==='manual'&&Object.values(saleTipAllocation()).reduce((a,b)=>a+b,0)!==cents(d.tip))return 'Allocate the full guest tip before checkout.';if(!saleWalletConfirmed())return 'Wait for the customer wallet payment to be confirmed.';if(saleGiftNeeded()>0&&Number(state.giftCardBalances[String(d.giftCardCode||'').trim().toUpperCase()]||0)+.001<saleGiftNeeded())return 'Enter a demo gift card with enough balance.';return ''}
  function serviceTenders(){if(state.payment!=='split')return [{method:state.payment,label:paymentLabel(state.payment),amount:total()}];const card=Math.round((cardBase('split')-methodDiscount('credit',cardBase('split'))+paymentFee('split'))*100)/100,cash=Number(state.splitCashPortion||0),other=Math.round((total()-card-cash)*100)/100;return [{method:'credit',label:'Card',amount:card},...(cash>0?[{method:'cash',label:'Cash',amount:cash}]:[]),{method:state.splitOtherMethod,label:paymentLabel(state.splitOtherMethod),amount:other}]}
